/**
 * Returns the state/province/county options for a given country, or an
 * empty array if this store has no subdivision data for that country (in
 * which case the state/province field should fall back to free text —
 * see StateSelect).
 */
export function getStatesForCountry(countryCode?: string): StateOption[] {
  if (!countryCode) return []
  return STATES_BY_COUNTRY[countryCode.toLowerCase()] ?? []
}
